/// <summary>
/// Cross-component notification hub for inventory alerts.
/// Scoped per circuit so each user has independent state.
/// Components subscribe to <see cref="OnAlertCountChanged"/> to get notified
/// when any component fetches fresh alert data.
/// </summary>
public sealed class AlertNotificationService : IDisposable
{
    private int _latestLowStockCount;
    private CancellationTokenSource? _pollCts;
    private int _subscriberCount;

    public int LatestLowStockCount => _latestLowStockCount;

    /// <summary>
    /// Raised when new alert data is available.
    /// Subscribers must marshal to their own sync context (InvokeAsync) before touching UI.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>Publish a new count and notify all subscribers.</summary>
    public async Task PublishCountAsync(int count)
    {
        _latestLowStockCount = count;
        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }

    /// <summary>
    /// Starts background polling. Polling runs as long as at least one subscriber
    /// has called StartPolling. Ref-counted so multiple components can request it.
    /// </summary>
    public void StartPolling(
        InventoryAlertService alertService,
        WarehouseStateService warehouseState,
        Func<Func<Task>, Task> invokeAsync)
    {
        _subscriberCount++;
        if (_pollCts is not null) return; // already running

        _pollCts = new CancellationTokenSource();
        var token = _pollCts.Token;

        _ = Task.Run(async () =>
        {
            using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            // Fire immediately on start, then every 10 s
            do
            {
                try
                {
                    var count = await alertService.GetLowStockCountAsync(
                        warehouseState.CurrentWarehouseId);

                    await invokeAsync(async () => await PublishCountAsync(count));
                }
                catch (ObjectDisposedException) { break; }
                catch (OperationCanceledException) { break; }
            }
            while (!token.IsCancellationRequested && await timer.WaitForNextTickAsync(token));
        }, token);
    }

    /// <summary>Decrement ref count; stop polling when it reaches zero.</summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _pollCts?.Cancel();
            _pollCts?.Dispose();
            _pollCts = null;
        }
    }

    public void Dispose()
    {
        _pollCts?.Cancel();
        _pollCts?.Dispose();
        _pollCts = null;
    }
}

