@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState

<div class="warehouse-selector">
    <label class="warehouse-label" for="warehouseSelect">Warehouse:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }
}

.warehouse-selector {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.warehouse-label {
    white-space: nowrap;
    font-weight: 500;
}

.warehouse-selector .form-select {
    max-width: 280px;
}

@rendermode InteractiveServer
@implements IDisposable
@inject AlertNotificationService AlertNotification

<span class="alert-badge-wrapper">
    @ChildContent
    @if (_count > 0)
    {
        <span class="badge bg-danger alert-badge">@_count</span>
    }
</span>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    private int _count;

    protected override void OnInitialized()
    {
        _count = AlertNotification.LatestLowStockCount;
        AlertNotification.OnAlertCountChanged += HandleAlertChanged;
    }

    private async Task HandleAlertChanged()
    {
        _count = AlertNotification.LatestLowStockCount;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertNotification.OnAlertCountChanged -= HandleAlertChanged;
    }
}

.alert-badge-wrapper {
    position: relative;
    display: inline-flex;
    align-items: center;
}

.alert-badge {
    position: absolute;
    top: -6px;
    right: -10px;
    font-size: 0.65rem;
    padding: 0.2em 0.45em;
    border-radius: 999px;
}

