                <span class="text-muted">every 10 seconds</span>
            </div>
        </div>
    </div>
</div>

<div class="alert @(_lowStockCount > 5 ? "alert-danger" : _lowStockCount > 0 ? "alert-warning" : "alert-success")">
    @if (_lowStockCount == 0)
    {
        <strong>All clear!</strong> <span>No items below minimum stock levels.</span>
    }
    else if (_lowStockCount <= 5)
    {
        <strong>Attention:</strong> <span>@_lowStockCount items are running low at @_currentWarehouseName.</span>
    }
    else
    {
        <strong>Critical:</strong> <span>@_lowStockCount items are below minimum stock at @_currentWarehouseName. Immediate restocking recommended.</span>
    }
</div>

@code {
    private int _lowStockCount;
    private string _currentWarehouseName = string.Empty;

    protected override void OnInitialized()
    {
        UpdateWarehouseName();

        // Subscribe to cross-component alert notifications
        AlertNotification.OnAlertCountChanged += HandleAlertChanged;

        // Subscribe to warehouse changes so the dashboard refreshes immediately
        WarehouseState.OnChange += HandleWarehouseChanged;

        // Start polling — ref-counted, stops when this component disposes
        AlertNotification.StartPolling(AlertService, WarehouseState, InvokeAsync);
    }

    private async Task HandleAlertChanged()
    {
        _lowStockCount = AlertNotification.LatestLowStockCount;
        await InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged()
    {
        UpdateWarehouseName();
        InvokeAsync(StateHasChanged);
    }

    private void UpdateWarehouseName()
    {
        _currentWarehouseName = WarehouseState.Warehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId)?.Name
            ?? WarehouseState.CurrentWarehouseId;
    }

    public void Dispose()
    {
        AlertNotification.OnAlertCountChanged -= HandleAlertChanged;
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertNotification.StopPolling();
    }
}

